// ReviewCarryRequest: レビューの文書（決定 0214・0218）の 1 つの対象を、開いた図面の文書の版へ移す。要素の参照を図面の要素の ID で引き、参照ごとに unchanged・changed・removed を返す。場所と図形に元の版のハッシュと状態を書き、対象のハッシュを文書のハッシュにする。2D の点は動かさない。移した文書は blobs の file で返す。小版 43 から
type ReviewCarryRequest struct {
	// メッセージのスキーマの大版。今は 1
	V *int64 `json:"v,omitempty"`

	// 予算の単位ごとの上限。書かない単位は既定値にする（決定 0010）
	Budget *Budget `json:"budget,omitempty"`

	// 予算で止まったとき、止まった所までの結果を求める。書かなければ false（決定 0010）
	Partial *bool `json:"partial,omitempty"`

	// 診断ごとに返す場所の数。書かなければ 16（決定 0009）
	MaxPlaces *int64 `json:"max_places,omitempty"`

	// 時間の上限（ミリ秒）。ネイティブの境界が時計を見て止める。止まる所は環境で変わる。wasm では受け付けない（決定 0010）
	TimeLimitMs *int64 `json:"time_limit_ms,omitempty"`

	// op の名前
	Op string `json:"op,omitempty"`

	// 新しい版の文書の名前。open で作ったもの。小版 44 から、IFC の建物モデルの文書も渡せ、要素の参照を建物モデルの要素の ID とハッシュで引く
	Doc *string `json:"doc,omitempty"`

	// レビューの文書の入力の名前（zm_push で渡した JSON）
	Review *string `json:"review,omitempty"`

	// 移す対象の ID。レビューの文書の targets の id
	Target *string `json:"target,omitempty"`

	// 返す最初の参照の位置。前の応答の next_offset を渡す。書かなければ 0
	Offset *int64 `json:"offset,omitempty"`

	// 返す参照の数の上限。書かなければ 1000
	Limit *int64 `json:"limit,omitempty"`
}

// MarshalJSON は、目印の欄を入れて書く。
